#!/usr/bin/env bash
set -Eeuo pipefail

# AI: below section was generated by an AI
# Safely merge official WLED, build the selected target, package it, and
# optionally publish both Git and firmware artifacts.

readonly SCRIPT_NAME="${0##*/}"
readonly OFFICIAL_WLED_URL="https://github.com/Aircoookie/WLED.git"
readonly DEFAULT_PROJECT_NAME="loomx-wled"
readonly DEFAULT_PIO_ENV="esp32dev"
readonly DEPLOY_ENV_FILE=".env.wled-deploy"

dry_run=false
skip_merge=false
push_enabled=true
upload_enabled=true
cli_branch=""
cli_pio_env=""
pio_env=""
custom_branch=""
upstream_branch=""
upstream_commit=""
git_commit=""
release_binary=""
checksum_file=""
checksum=""
remote_release_path=""
pushed="no"
uploaded="no"
deployment_status="not_started"
transfer_command=""
declare -a PIO_COMMAND=()

usage() {
  cat <<'USAGE'
Update, build, and deploy the Loomx WLED firmware.

Usage:
  scripts/update-build-deploy-wled.sh [options]

Options:
  --branch <branch>  Custom branch to update (default: WLED_CUSTOM_BRANCH or
                     the currently checked-out branch).
  --env <name>       PlatformIO environment (default: WLED_PIO_ENV or esp32dev
                     when that environment exists).
  --no-push          Build and package without pushing the custom branch.
  --no-upload        Build and package without uploading firmware.
  --dry-run          Validate and print the plan without fetching, merging,
                     building, pushing, uploading, or creating files.
  --skip-merge       Update from origin, but do not merge upstream WLED.
  --help             Show this help.

Configuration:
  Copy .env.wled-deploy.example to .env.wled-deploy and fill in the values.
  The parser accepts one literal KEY=VALUE assignment per line. It does not
  execute shell code or expand variables.
USAGE
}

fail() {
  local exit_code="$1"
  shift
  printf 'Error: %s\n' "$*" >&2
  exit "$exit_code"
}

on_error() {
  local exit_code=$?
  local line_number="${BASH_LINENO[0]:-unknown}"
  printf 'Error: command failed at line %s (exit %s): %s\n' \
    "$line_number" "$exit_code" "$BASH_COMMAND" >&2
  exit "$exit_code"
}
trap on_error ERR

trim_whitespace() {
  local value="$1"
  value="${value#"${value%%[![:space:]]*}"}"
  value="${value%"${value##*[![:space:]]}"}"
  printf '%s' "$value"
}

set_config_value_if_empty() {
  local key="$1"
  local value="$2"

  case "$key" in
    WLED_CUSTOM_BRANCH)
      [[ -n "${WLED_CUSTOM_BRANCH:-}" ]] || WLED_CUSTOM_BRANCH="$value"
      ;;
    WLED_PIO_ENV)
      [[ -n "${WLED_PIO_ENV:-}" ]] || WLED_PIO_ENV="$value"
      ;;
    WLED_PROJECT_NAME)
      [[ -n "${WLED_PROJECT_NAME:-}" ]] || WLED_PROJECT_NAME="$value"
      ;;
    DEPLOY_HOST)
      [[ -n "${DEPLOY_HOST:-}" ]] || DEPLOY_HOST="$value"
      ;;
    DEPLOY_USER)
      [[ -n "${DEPLOY_USER:-}" ]] || DEPLOY_USER="$value"
      ;;
    DEPLOY_PATH)
      [[ -n "${DEPLOY_PATH:-}" ]] || DEPLOY_PATH="$value"
      ;;
    DEPLOY_PORT)
      [[ -n "${DEPLOY_PORT:-}" ]] || DEPLOY_PORT="$value"
      ;;
    DEPLOY_UPDATE_LATEST)
      [[ -n "${DEPLOY_UPDATE_LATEST:-}" ]] || DEPLOY_UPDATE_LATEST="$value"
      ;;
    DEPLOY_LATEST_NAME)
      [[ -n "${DEPLOY_LATEST_NAME:-}" ]] || DEPLOY_LATEST_NAME="$value"
      ;;
    *)
      fail 11 "Unsupported key '$key' in $DEPLOY_ENV_FILE."
      ;;
  esac
}

load_deploy_environment() {
  local file_path="$1"
  local raw_line=""
  local line=""
  local key=""
  local value=""

  [[ -f "$file_path" ]] || return 0

  while IFS= read -r raw_line || [[ -n "$raw_line" ]]; do
    line="${raw_line%$'\r'}"
    [[ -z "$(trim_whitespace "$line")" ]] && continue
    [[ "$line" =~ ^[[:space:]]*# ]] && continue
    if [[ ! "$line" =~ ^[[:space:]]*([A-Za-z_][A-Za-z0-9_]*)=(.*)$ ]]; then
      fail 11 "Invalid line in $DEPLOY_ENV_FILE: $raw_line"
    fi

    key="${BASH_REMATCH[1]}"
    value="$(trim_whitespace "${BASH_REMATCH[2]}")"
    if [[ ${#value} -ge 2 ]]; then
      if [[ "${value:0:1}" == '"' && "${value: -1}" == '"' ]] ||
        [[ "${value:0:1}" == "'" && "${value: -1}" == "'" ]]; then
        value="${value:1:${#value}-2}"
      fi
    fi
    set_config_value_if_empty "$key" "$value"
  done <"$file_path"
}

command_exists() {
  command -v "$1" >/dev/null 2>&1
}

select_platformio_command() {
  if command_exists pio; then
    PIO_COMMAND=(pio)
  elif python3 -c 'import platformio' >/dev/null 2>&1; then
    PIO_COMMAND=(python3 -m platformio)
  elif [[ -x "${HOME}/.platformio/penv/bin/pio" ]]; then
    PIO_COMMAND=("${HOME}/.platformio/penv/bin/pio")
  else
    fail 12 "PlatformIO was not found as 'pio', 'python3 -m platformio', or ${HOME}/.platformio/penv/bin/pio."
  fi
}

check_prerequisites() {
  local missing=()
  local command_name=""

  for command_name in git python3 node npm ssh shasum awk sed tr; do
    command_exists "$command_name" || missing+=("$command_name")
  done
  if command_exists scp; then
    transfer_command="scp"
  elif command_exists rsync; then
    transfer_command="rsync"
  else
    missing+=("scp or rsync")
  fi

  if ((${#missing[@]} > 0)); then
    fail 12 "Missing required commands: ${missing[*]}"
  fi
  select_platformio_command

  local node_major=""
  node_major="$(node -p 'process.versions.node.split(".")[0]')"
  if [[ "$node_major" =~ ^[0-9]+$ ]] && ((node_major < 20)); then
    printf 'Warning: WLED declares Node.js 20 or newer; found %s.\n' \
      "$(node --version)" >&2
  fi
}

list_platformio_environments() {
  "${PIO_COMMAND[@]}" project config --json-output |
    python3 -c '
import json
import sys

for section, _options in json.load(sys.stdin):
    if section.startswith("env:"):
        print(section[4:])
'
}

environment_exists() {
  local requested="$1"
  list_platformio_environments |
    python3 -c '
import sys

requested = sys.argv[1]
environments = {line.rstrip("\n") for line in sys.stdin}
raise SystemExit(0 if requested in environments else 1)
' "$requested"
}

detect_upstream_default_branch() {
  local detected=""
  local remote_target="upstream"
  if ! git remote get-url upstream >/dev/null 2>&1; then
    remote_target="$OFFICIAL_WLED_URL"
  fi

  detected="$(
    git symbolic-ref --quiet --short refs/remotes/upstream/HEAD 2>/dev/null |
      sed 's#^upstream/##' ||
      true
  )"
  if [[ -z "$detected" ]]; then
    detected="$(
      git ls-remote --symref "$remote_target" HEAD 2>/dev/null |
        awk '$1 == "ref:" {sub("refs/heads/", "", $2); print $2; exit}' ||
        true
    )"
  fi
  if [[ -z "$detected" ]]; then
    local candidate=""
    for candidate in main master; do
      if git show-ref --verify --quiet "refs/remotes/upstream/$candidate"; then
        detected="$candidate"
        break
      fi
    done
  fi
  [[ -n "$detected" ]] ||
    fail 21 "Could not detect the default branch for the upstream remote."
  printf '%s' "$detected"
}

validate_deployment_configuration() {
  local missing=()

  [[ -n "${DEPLOY_HOST:-}" ]] || missing+=("DEPLOY_HOST")
  [[ -n "${DEPLOY_USER:-}" ]] || missing+=("DEPLOY_USER")
  [[ -n "${DEPLOY_PATH:-}" ]] || missing+=("DEPLOY_PATH")
  if ((${#missing[@]} > 0)); then
    fail 13 "Upload is enabled, but these settings are missing: ${missing[*]}. Configure $DEPLOY_ENV_FILE or use --no-upload."
  fi

  if [[ ! "${DEPLOY_PORT:-22}" =~ ^[0-9]+$ ]] ||
    ((DEPLOY_PORT < 1 || DEPLOY_PORT > 65535)); then
    fail 13 "DEPLOY_PORT must be an integer from 1 to 65535."
  fi
  [[ "$DEPLOY_USER" != -* && "$DEPLOY_USER" =~ ^[A-Za-z0-9._-]+$ ]] ||
    fail 13 "DEPLOY_USER contains unsupported characters."
  [[ "$DEPLOY_HOST" != -* && "$DEPLOY_HOST" =~ ^[A-Za-z0-9._:%-]+$ ]] ||
    fail 13 "DEPLOY_HOST contains unsupported characters."
  [[ "$DEPLOY_PATH" == /* && "$DEPLOY_PATH" != *$'\n'* ]] ||
    fail 13 "DEPLOY_PATH must be an absolute path without newlines."
  [[ "$DEPLOY_LATEST_NAME" != */* &&
    "$DEPLOY_LATEST_NAME" =~ ^[A-Za-z0-9._-]+$ ]] ||
    fail 13 "DEPLOY_LATEST_NAME must be a simple filename."
  [[ "$DEPLOY_UPDATE_LATEST" == "0" ||
    "$DEPLOY_UPDATE_LATEST" == "1" ]] ||
    fail 13 "DEPLOY_UPDATE_LATEST must be 0 or 1."
}

remote_quote() {
  local value="$1"
  local escaped=""
  escaped="$(printf '%s' "$value" | sed "s/'/'\"'\"'/g")"
  printf "'%s'" "$escaped"
}

write_manifest() {
  local manifest_path="$1"
  local file_size=""
  file_size="$(python3 -c 'import os,sys; print(os.path.getsize(sys.argv[1]))' "$release_binary")"

  python3 - \
    "$manifest_path" \
    "${release_binary##*/}" \
    "$checksum" \
    "$pio_env" \
    "$git_commit" \
    "$upstream_commit" \
    "$build_timestamp" \
    "$custom_branch" \
    "$file_size" \
    "$deployment_status" \
    "$remote_release_path" <<'PY'
import json
import pathlib
import sys

(
    manifest_path,
    filename,
    checksum,
    environment,
    commit_sha,
    upstream_sha,
    timestamp,
    branch,
    file_size,
    deployment_status,
    remote_path,
) = sys.argv[1:]

manifest = {
    "filename": filename,
    "checksum": checksum,
    "build_environment": environment,
    "git_commit_sha": commit_sha,
    "upstream_commit_sha": upstream_sha,
    "build_timestamp": timestamp,
    "branch": branch,
    "file_size": int(file_size),
    "deployment_status": deployment_status,
    "remote_path": remote_path or None,
}
path = pathlib.Path(manifest_path)
path.write_text(json.dumps(manifest, indent=2) + "\n", encoding="utf-8")
PY
}

upload_file() {
  local source_path="$1"
  local destination_path="$2"
  local target="${DEPLOY_USER}@${DEPLOY_HOST}"
  local quoted_destination=""
  quoted_destination="$(remote_quote "$destination_path")"

  if [[ "$transfer_command" == "scp" ]]; then
    scp -P "$DEPLOY_PORT" "$source_path" \
      "${target}:${quoted_destination}"
  else
    rsync -a -e "ssh -p $DEPLOY_PORT" "$source_path" \
      "${target}:${quoted_destination}"
  fi
}

upload_release() {
  local target="${DEPLOY_USER}@${DEPLOY_HOST}"
  local checksum_name="${checksum_file##*/}"
  local remote_checksum_path="${DEPLOY_PATH%/}/${checksum_name}"
  local temporary_suffix=".uploading-${build_timestamp}-$$"
  local temporary_binary="${remote_release_path}${temporary_suffix}"
  local temporary_checksum="${remote_checksum_path}${temporary_suffix}"
  local remote_digest=""
  local quoted_deploy_path=""
  local quoted_temporary_binary=""
  local quoted_temporary_checksum=""
  local quoted_release=""
  local quoted_checksum=""

  quoted_deploy_path="$(remote_quote "$DEPLOY_PATH")"
  quoted_temporary_binary="$(remote_quote "$temporary_binary")"
  quoted_temporary_checksum="$(remote_quote "$temporary_checksum")"
  quoted_release="$(remote_quote "$remote_release_path")"
  quoted_checksum="$(remote_quote "$remote_checksum_path")"

  ssh -p "$DEPLOY_PORT" "$target" \
    "mkdir -p $quoted_deploy_path"
  upload_file "$release_binary" "$temporary_binary"
  upload_file "$checksum_file" "$temporary_checksum"

  remote_digest="$(
    ssh -p "$DEPLOY_PORT" "$target" \
      "if command -v sha256sum >/dev/null 2>&1; then sha256sum $quoted_temporary_binary | cut -d ' ' -f 1; elif command -v shasum >/dev/null 2>&1; then shasum -a 256 $quoted_temporary_binary | cut -d ' ' -f 1; else echo 'No SHA-256 utility found on server.' >&2; exit 127; fi"
  )"
  remote_digest="$(printf '%s' "$remote_digest" | tr '[:upper:]' '[:lower:]')"
  [[ "$remote_digest" == "$checksum" ]] ||
    fail 42 "Uploaded firmware checksum mismatch; temporary files were not published."

  ssh -p "$DEPLOY_PORT" "$target" \
    "mv $quoted_temporary_binary $quoted_release && mv $quoted_temporary_checksum $quoted_checksum"

  if [[ "$DEPLOY_UPDATE_LATEST" == "1" ]]; then
    local latest_temporary="${DEPLOY_PATH%/}/.${DEPLOY_LATEST_NAME}.tmp-${build_timestamp}-$$"
    local latest_path="${DEPLOY_PATH%/}/${DEPLOY_LATEST_NAME}"
    local quoted_latest_temporary=""
    local quoted_latest_path=""
    local quoted_filename=""
    quoted_latest_temporary="$(remote_quote "$latest_temporary")"
    quoted_latest_path="$(remote_quote "$latest_path")"
    quoted_filename="$(remote_quote "${release_binary##*/}")"
    ssh -p "$DEPLOY_PORT" "$target" \
      "ln -sfn $quoted_filename $quoted_latest_temporary && mv -f $quoted_latest_temporary $quoted_latest_path"
  fi
}

while (($# > 0)); do
  case "$1" in
    --branch)
      (($# >= 2)) || fail 2 "--branch requires a value."
      cli_branch="$2"
      shift 2
      ;;
    --env)
      (($# >= 2)) || fail 2 "--env requires a value."
      cli_pio_env="$2"
      shift 2
      ;;
    --no-push)
      push_enabled=false
      shift
      ;;
    --no-upload)
      upload_enabled=false
      shift
      ;;
    --dry-run)
      dry_run=true
      shift
      ;;
    --skip-merge)
      skip_merge=true
      shift
      ;;
    --help|-h)
      usage
      exit 0
      ;;
    *)
      fail 2 "Unknown option: $1. Run $SCRIPT_NAME --help."
      ;;
  esac
done

SCRIPT_DIRECTORY="$(
  cd "$(dirname "${BASH_SOURCE[0]}")" >/dev/null 2>&1
  pwd -P
)"
readonly SCRIPT_DIRECTORY
REPOSITORY_ROOT="$(
  cd "$SCRIPT_DIRECTORY/.." >/dev/null 2>&1
  pwd -P
)"
readonly REPOSITORY_ROOT
cd "$REPOSITORY_ROOT"

git rev-parse --is-inside-work-tree >/dev/null 2>&1 ||
  fail 10 "$REPOSITORY_ROOT is not a Git repository."
[[ "$(git rev-parse --show-toplevel)" == "$REPOSITORY_ROOT" ]] ||
  fail 10 "The script must live directly under this repository's scripts directory."

load_deploy_environment "$REPOSITORY_ROOT/$DEPLOY_ENV_FILE"
check_prerequisites

custom_branch="${cli_branch:-${WLED_CUSTOM_BRANCH:-}}"
if [[ -z "$custom_branch" ]]; then
  custom_branch="$(git branch --show-current)"
fi
[[ -n "$custom_branch" ]] ||
  fail 20 "HEAD is detached. Supply --branch or WLED_CUSTOM_BRANCH."
git check-ref-format --branch "$custom_branch" >/dev/null 2>&1 ||
  fail 20 "Invalid custom branch name: $custom_branch"
git show-ref --verify --quiet "refs/heads/$custom_branch" ||
  fail 20 "Local custom branch '$custom_branch' does not exist."

pio_env="${cli_pio_env:-${WLED_PIO_ENV:-}}"
if [[ -z "$pio_env" ]]; then
  if environment_exists "$DEFAULT_PIO_ENV"; then
    pio_env="$DEFAULT_PIO_ENV"
  else
    fail 30 "No PlatformIO environment was selected and the documented default '$DEFAULT_PIO_ENV' does not exist."
  fi
fi
environment_exists "$pio_env" ||
  fail 30 "PlatformIO environment '$pio_env' does not exist."

WLED_PROJECT_NAME="${WLED_PROJECT_NAME:-$DEFAULT_PROJECT_NAME}"
DEPLOY_PORT="${DEPLOY_PORT:-22}"
DEPLOY_UPDATE_LATEST="${DEPLOY_UPDATE_LATEST:-1}"
DEPLOY_LATEST_NAME="${DEPLOY_LATEST_NAME:-latest.bin}"
[[ "$WLED_PROJECT_NAME" =~ ^[A-Za-z0-9._-]+$ ]] ||
  fail 31 "WLED_PROJECT_NAME contains unsupported filename characters."

working_tree_status="$(git status --porcelain --untracked-files=all)"
if [[ -n "$working_tree_status" ]]; then
  if [[ "$dry_run" == true ]]; then
    printf 'Dry-run warning: the working tree is not clean; a real run would stop.\n' >&2
  else
    printf '%s\n' "$working_tree_status" >&2
    fail 14 "Working tree is not clean. Commit or remove the listed changes; the script will not stash or discard them."
  fi
fi

upstream_url="$(git remote get-url upstream 2>/dev/null || true)"
if [[ -z "$upstream_url" ]]; then
  if [[ "$dry_run" == true ]]; then
    printf 'Would add upstream remote: %s\n' "$OFFICIAL_WLED_URL"
  else
    git remote add upstream "$OFFICIAL_WLED_URL"
    upstream_url="$OFFICIAL_WLED_URL"
  fi
elif [[ "$upstream_url" != "$OFFICIAL_WLED_URL" &&
  "$upstream_url" != "https://github.com/wled/WLED.git" &&
  "$upstream_url" != "git@github.com:Aircoookie/WLED.git" &&
  "$upstream_url" != "git@github.com:wled/WLED.git" ]]; then
  printf 'Warning: existing upstream URL is not the recognized official WLED URL: %s\n' \
    "$upstream_url" >&2
fi

git remote get-url origin >/dev/null 2>&1 ||
  fail 22 "The origin remote is missing."

upstream_branch="$(detect_upstream_default_branch)"
upstream_commit="$(
  git rev-parse "refs/remotes/upstream/$upstream_branch" 2>/dev/null ||
    printf 'not-fetched'
)"

printf 'Repository:          %s\n' "$REPOSITORY_ROOT"
printf 'Custom branch:       %s\n' "$custom_branch"
printf 'Upstream:            %s (%s)\n' \
  "${upstream_url:-$OFFICIAL_WLED_URL}" "$upstream_branch"
printf 'PlatformIO env:      %s\n' "$pio_env"
printf 'Push enabled:        %s\n' "$push_enabled"
printf 'Upload enabled:      %s\n' "$upload_enabled"
printf 'Merge enabled:       %s\n' "$([[ "$skip_merge" == true ]] && printf false || printf true)"

if [[ "$dry_run" == true ]]; then
  printf '\nDry run only; no repository, build, release, or server state was changed.\n'
  printf 'Would fetch origin and upstream, fast-forward from origin/%s, ' "$custom_branch"
  if [[ "$skip_merge" == true ]]; then
    printf 'skip the upstream merge, '
  else
    printf 'back up the branch and merge upstream/%s, ' "$upstream_branch"
  fi
  printf 'build %s, package a checksummed release' "$pio_env"
  [[ "$push_enabled" == true ]] && printf ', push origin/%s' "$custom_branch"
  if [[ "$upload_enabled" == true ]]; then
    if [[ -n "${DEPLOY_HOST:-}" && -n "${DEPLOY_USER:-}" &&
      -n "${DEPLOY_PATH:-}" ]]; then
      printf ', and upload to %s@%s:%s' \
        "$DEPLOY_USER" "$DEPLOY_HOST" "$DEPLOY_PATH"
    else
      printf ', and require deployment settings before upload'
    fi
  fi
  printf '.\n'
  exit 0
fi

if [[ "$upload_enabled" == true ]]; then
  validate_deployment_configuration
fi

printf '\nFetching origin and upstream...\n'
git fetch --prune origin
git fetch --prune upstream
git switch "$custom_branch"
git show-ref --verify --quiet "refs/remotes/origin/$custom_branch" ||
  fail 23 "Remote branch origin/$custom_branch does not exist."
git merge --ff-only "origin/$custom_branch"

upstream_branch="$(detect_upstream_default_branch)"
git show-ref --verify --quiet "refs/remotes/upstream/$upstream_branch" ||
  fail 24 "Fetched upstream branch upstream/$upstream_branch does not exist."
upstream_commit="$(git rev-parse "refs/remotes/upstream/$upstream_branch")"

build_timestamp="$(date -u '+%Y-%m-%d_%H%M%S')"
if [[ "$skip_merge" == false ]]; then
  safe_branch="${custom_branch//\//-}"
  backup_branch="backup/${safe_branch}-before-upstream-${build_timestamp}"
  git branch "$backup_branch" HEAD
  printf 'Created pre-merge backup branch: %s\n' "$backup_branch"

  if ! git merge --no-edit "upstream/$upstream_branch"; then
    printf '\nUpstream merge stopped with conflicts. No build, push, or upload was attempted.\n' >&2
    printf 'Conflicted files:\n' >&2
    git diff --name-only --diff-filter=U >&2
    printf '\nResolve each file, then run:\n  git add <resolved-files>\n  git commit\n' >&2
    printf 'To abandon the merge instead, run:\n  git merge --abort\n' >&2
    exit 40
  fi
fi

printf '\nBuilding PlatformIO environment: %s\n' "$pio_env"
npm ci
if [[ -f loomx/tools/build-ui.mjs ]]; then
  node loomx/tools/build-ui.mjs
else
  npm run build
fi
"${PIO_COMMAND[@]}" run -e "$pio_env"

firmware_binary="$REPOSITORY_ROOT/.pio/build/$pio_env/firmware.bin"
[[ -s "$firmware_binary" ]] ||
  fail 32 "Firmware binary is missing or empty: $firmware_binary"

post_build_status="$(git status --porcelain --untracked-files=all)"
if [[ -n "$post_build_status" ]]; then
  printf '%s\n' "$post_build_status" >&2
  fail 33 "The build unexpectedly changed tracked or unignored files. Review them before pushing."
fi

git_commit="$(git rev-parse HEAD)"
short_commit="$(git rev-parse --short=8 HEAD)"
release_directory="$REPOSITORY_ROOT/releases"
release_filename="${WLED_PROJECT_NAME}-${pio_env}-${build_timestamp}-${short_commit}.bin"
release_binary="$release_directory/$release_filename"
checksum_file="${release_binary}.sha256"
manifest_path="$release_directory/manifest.json"
mkdir -p "$release_directory"
cp "$firmware_binary" "$release_binary"
[[ -s "$release_binary" ]] ||
  fail 34 "Packaged firmware is missing or empty: $release_binary"
checksum="$(shasum -a 256 "$release_binary" | awk '{print $1}')"
printf '%s  %s\n' "$checksum" "$release_filename" >"$checksum_file"

deployment_status="built"
write_manifest "$manifest_path"

if [[ "$push_enabled" == true ]]; then
  printf '\nPushing successful build to origin/%s...\n' "$custom_branch"
  git push origin "HEAD:refs/heads/$custom_branch"
  pushed="yes"
  deployment_status="pushed"
  write_manifest "$manifest_path"
fi

if [[ "$upload_enabled" == true ]]; then
  remote_release_path="${DEPLOY_PATH%/}/$release_filename"
  printf '\nUploading firmware to %s@%s:%s...\n' \
    "$DEPLOY_USER" "$DEPLOY_HOST" "$remote_release_path"
  upload_release
  uploaded="yes"
  deployment_status="uploaded"
  write_manifest "$manifest_path"
fi

printf '\nWLED update/build/deploy complete\n'
printf 'Custom branch:       %s\n' "$custom_branch"
printf 'Upstream commit:     %s\n' "$upstream_commit"
printf 'PlatformIO env:      %s\n' "$pio_env"
printf 'Local firmware:      %s\n' "$release_binary"
printf 'SHA-256:             %s\n' "$checksum"
printf 'Remote path:         %s\n' "${remote_release_path:-not uploaded}"
printf 'Branch pushed:       %s\n' "$pushed"
printf 'Firmware uploaded:   %s\n' "$uploaded"
# AI: end
